#!/usr/bin/env python3
"""
Self-contained demo of the semantic entropy framework for monotone Boolean functions.
"""
import math
from itertools import product
from typing import Callable, Dict, List, Optional, Tuple

BoolVec = Tuple[int, ...]
MonotoneFn = Callable[[BoolVec], bool]

def all_bool_vecs(n):
    return list(product([0, 1], repeat=n))

def leq(x, y):
    return all(xi <= yi for xi, yi in zip(x, y))

def hamming_dist(x, y):
    return sum(xi != yi for xi, yi in zip(x, y))

def up_sat(f, x, n):
    return [z for z in all_bool_vecs(n) if leq(x, z) and f(z)]

def semantic_mass(f, x, n):
    return len(up_sat(f, x, n))

def semantic_entropy(f, x, n):
    mass = semantic_mass(f, x, n)
    return math.log2(mass) if mass > 0 else 0.0

def entropy_drop(f, x, y, n):
    return semantic_entropy(f, x, n) - semantic_entropy(f, y, n)

def semantic_entropy_profile(f, n):
    return {x: semantic_entropy(f, x, n) for x in all_bool_vecs(n)}

def max_entropy_drop(f, n):
    best, bx, by_ = 0.0, None, None
    vecs = all_bool_vecs(n)
    for x in vecs:
        for y in vecs:
            if leq(x, y):
                d = entropy_drop(f, x, y, n)
                if d > best: best, bx, by_ = d, x, y
    return best, bx, by_

def max_cover_entropy_drop(f, n):
    best = 0.0
    for x in all_bool_vecs(n):
        for i in range(n):
            if x[i] == 0:
                y = list(x); y[i] = 1; y = tuple(y)
                best = max(best, entropy_drop(f, x, y, n))
    return best

def depth_lower_bound(f, n, k=2):
    md, _, _ = max_entropy_drop(f, n)
    return md / math.log2(k)

def make_and(n): return lambda x: all(xi == 1 for xi in x)
def make_or(n): return lambda x: any(xi == 1 for xi in x)
def make_threshold(n, t): return lambda x: sum(x) >= t
def make_majority(n): return make_threshold(n, n // 2 + 1)

def verify_antitonicity(f, n):
    profile = semantic_entropy_profile(f, n)
    for x in all_bool_vecs(n):
        for y in all_bool_vecs(n):
            if leq(x, y) and profile[y] > profile[x] + 1e-12:
                return False
    return True

def format_vec(v):
    return ''.join(str(x) for x in v)

# ─── DEMO ───
print("=" * 60)
print("  SEMANTIC ENTROPY FRAMEWORK DEMO")
print("=" * 60)
n = 3
f_or = make_or(n)
zero, one = tuple(0 for _ in range(n)), tuple(1 for _ in range(n))
print(f"
OR function on {n} bits:")
print(f"  SemEnt(OR, {format_vec(zero)}) = {semantic_entropy(f_or, zero, n):.3f}")
print(f"  SemEnt(OR, {format_vec(one)}) = {semantic_entropy(f_or, one, n):.3f}")
print(f"  Entropy drop = {entropy_drop(f_or, zero, one, n):.3f}")
print(f"  Antitonicity verified: {verify_antitonicity(f_or, n)}")

print("
" + "=" * 60)
print("  Depth Lower Bounds (n=4, fan-in 2)")
print("=" * 60)
n = 4
for name, f in [("OR", make_or(n)), ("MAJ", make_majority(n)),
                 ("Thr>=2", make_threshold(n, 2)), ("Thr>=3", make_threshold(n, 3))]:
    md, _, _ = max_entropy_drop(f, n)
    lb = depth_lower_bound(f, n, k=2)
    print(f"  {name:<10} max_drop={md:.3f}  depth_lb={lb:.3f}")

print("
All computations verified!")
